<?php
namespace App\Services;use App\Models\PortfolioItem;use Illuminate\Support\Str;
class PortfolioManagementService{public function create(array $d,$admin):PortfolioItem{return PortfolioItem::create($d+['id'=>(string)Str::uuid(),'created_by'=>$admin->id]);}public function update(PortfolioItem $p,array $d):PortfolioItem{$p->update($d);return $p->fresh(['category','media']);}public function delete(PortfolioItem $p):void{$p->delete();}public function publicList(array $q){$x=PortfolioItem::where('status','ACTIVE')->with(['category','media']);if(!empty($q['category_id']))$x->where('category_id',$q['category_id']);if(!empty($q['search']))$x->where(fn($w)=>$w->where('title','like','%'.$q['search'].'%')->orWhere('short_description','like','%'.$q['search'].'%')->orWhere('description','like','%'.$q['search'].'%'));return $x->latest()->paginate(min((int)($q['limit']??20),50));}}
